const messageText = $('Get Message From User').first().json.message.text || '';
const trimmedText = messageText.trim().toLowerCase();

// Гілка команди /start
if (trimmedText.startsWith('/start')) {
  return [{
    json: {
      command: 'start',
      isValid: true
    }
  }];
}

//Гілка команди /myalerts
if (trimmedText.startsWith('/myalerts')) {
  return [{
    json: {
      command: 'myalerts',
      isValid: true
    }
  }];
}

// Гілка команди /alerthelp
if (trimmedText.startsWith('/alerthelp')){
  return [{
    json: {
      command: 'alerthelp',
      isValid: true
    }
  }];
}
// Гілка команди /price
if (trimmedText.startsWith('/price')) {
  const parts = messageText.split(' ');
  const inputTicker = parts[1] ? parts[1].toLowerCase().trim() : '';

  const cryptoMap = {
    'btc': 'bitcoin', 'bitcoin': 'bitcoin',
    'eth': 'ethereum', 'ethereum': 'ethereum',
    'sol': 'solana', 'solana': 'solana'
  };

  const coinId = cryptoMap[inputTicker];

  return [{
    json: {
      command: 'price',
      isValid: !!coinId,
      coinId: coinId || null,
      requestedTicker: inputTicker.toUpperCase() || 'UNKNOWN'
    }
  }];
}

// Гілка команди /digest
if (trimmedText.startsWith('/digest')) {
  return [{
    json: {
      command: 'digest',
      isValid: true
    }
  }];
}

// Price alert
if (trimmedText.startsWith('/alert ')) {

  const parts = trimmedText.split(/\s+/);

  if (parts.length !== 4) {
    return [{
      json: {
        command: 'alert',
        isValid: false,
        error: 'Usage: /alert btc > 70000'
      }
    }];
  }

  const coin = parts[1].toLowerCase();
  const operator = parts[2];
  const price = Number(parts[3]);

  const allowedCoins = ['btc', 'eth', 'sol'];
  const allowedOperators = ['>', '<', '>=', '<=', '='];

  if (!allowedCoins.includes(coin)) {
    return [{
      json: {
        command: 'alert',
        isValid: false,
        error: 'Coin must be BTC, ETH or SOL.'
      }
    }];
  }

  if (!allowedOperators.includes(operator)) {
    return [{
      json: {
        command: 'alert',
        isValid: false,
        error: 'Operator must be >, <, >=, <= or ='
      }
    }];
  }

  if (isNaN(price) || price <= 0) {
    return [{
      json: {
        command: 'alert',
        isValid: false,
        error: 'Price must be a positive number.'
      }
    }];
  }

  return [{
    json: {
      command: 'alert',
      isValid: true,
      coin,
      operator,
      targetPrice: price
    }
  }];
}

// Якщо написали щось інше
return [{
  json: {
    command: 'unknown',
    isValid: false
  }
}];

const alerts = $input.all();

const keyboard = [];

const coinEmoji = {
    BTC: "₿",
    ETH: "♦️",
    SOL: "◎"
};

for (const item of alerts) {

    const alert = item.json;

    keyboard.push([
        {
            text:
            `🗑 ${coinEmoji[alert.coin] ?? "🪙"} ${alert.coin} ${alert.operator} $${Number(alert.target_price).toLocaleString()}`,

            callback_data:
            `delete_alert_${alert.alert_id}`
        }
    ]);

}

keyboard.push([
[
{
text:"❌ Cancel",
callback_data:"cancel_delete"
}
][0]
]);

return [
{
json:{
text:"🗑 Select an alert to delete:",
reply_markup:{
inline_keyboard:keyboard
}
}
}
];

const callback = $input.first().json.callback_query.data;

const alertId = callback.replace("delete_alert_", "");

return [
  {
    json: {
      alert_id: alertId
    }
  }
];

