const alerts = $('Get User Alerts').all();

return [
  {
    json: {
      alertCount: alerts.length
    }
  }
];

const alerts = $input.all();

if (alerts.length === 0) {
  return [
    {
      json: {
        messageText: "📭 *You don't have any active price alerts.*"
      }
    }
  ];
}

const coinEmoji = {
  BTC: "₿",
  ETH: "♦️",
  SOL: "◎"
};

let text = "🔔 *Your Active Price Alerts*\n\n";

for (const item of alerts) {
  const alert = item.json;

  const coin = String(alert.coin).toUpperCase();
  const emoji = coinEmoji[coin] ?? "🪙";

  const operator = alert.operator;
  const price = Number(alert.target_price).toLocaleString("en-US");

  text += `${emoji} *${coin}*   ${operator}   *$${price}*\n`;
}

text += `\n━━━━━━━━━━━━━━━`;
text += `\n*Total alerts:* ${alerts.length}`;

return [
  {
    json: {
      messageText: text
    }
  }
];

