const alerts = $input.all();

let maxId = 0;

for (const item of alerts) {

    const id = item.json.alert_id;

    if (!id) continue;

    const number = parseInt(id.replace('A', ''));

    if (!isNaN(number) && number > maxId) {
        maxId = number;
    }
}

const nextId =
    'A' + String(maxId + 1).padStart(6, '0');

return [{
    json: {
        alert_id: nextId
    }
}];

const data = $input.first().json;

const btc = data.bitcoin ?? {};
const eth = data.ethereum ?? {};
const sol = data.solana ?? {};

function line(name, data) {
    const price = Number(data.usd ?? 0);
    const change = Number(data.usd_24h_change ?? 0);

    const emoji = change >= 0 ? "🟢" : "🔴";
    const sign = change >= 0 ? "+" : "";

    return `${emoji} *${name}*

💵 Price: *$${price.toLocaleString()}*
📊 24h: *${sign}${change.toFixed(2)}%*

`;
}

let message = `📊 *CRYPTO DIGEST*

Here is the latest overview of the cryptocurrency market.

━━━━━━━━━━━━━━━

`;

message += line("BTC", btc);
message += line("ETH", eth);
message += line("SOL", sol);

message += `━━━━━━━━━━━━━━━

📈 Latest market snapshot.
🚀 Happy trading!`;

return [
  {
    json: {
      messageText: message,
    },
  },
];
